"""Every fish as one data record. Mechanics live in preview/fishing.js and never name a species.
Fields: name, latin, rarity, habitat, depth, periods, seasons, weather, bait, difficulty, behavior,
cm, kg, value, uses, clue (hint before discovery), note (revealed after catch), description."""
ALL = 'dawn,day,dusk,night,deep'; DAY = 'dawn,day,dusk'; NIGHT = 'night,deep'
RECORDS = []
def D(id, name, latin, rarity, hab, depth, periods, seasons, weather, bait, diff, beh, cm, kg, value, uses, clue, note, desc):
    RECORDS.append(dict(id=id, name=name, latin=latin, rarity=rarity, habitat=hab, depth=depth, periods=periods.split(','), seasons=seasons.split(','), weather=weather.split(','), bait=bait.split(','), difficulty=diff, behavior=beh, cm=list(cm), kg=list(kg), value=value, uses=uses.split(','), clue=clue, note=note, description=desc))
ANY = 'any'; P, ST, M, L, R = 'pond', 'stream', 'marsh', 'lake', 'reservoir'
# ---- woodland pond
D('minnow','Minnow','Phoxinus silvanus','common',P,'surface',DAY,ANY,ANY,'worm,dough,insect',1,'calm',(4,9),(.003,.02),2,'bait,food','Shoals at the surface wherever the sun is on the water.','Crafts into live baitfish.','Hardly a mouthful, and always in company. Where these flicker, larger things are watching.')
D('perch','Perch','Perca barrata','common',P,'mid',DAY,ANY,ANY,'worm,baitfish',2,'quick',(12,32),(.05,.7),6,'food','Hunts minnows at the edge of the lilies in daylight.','Spines are sharp. Mind your thumb.','Banded like shade under reeds, with fins the colour of a warning.')
D('roach','Roach','Rutilus rubens','common',P,'mid',ANY,ANY,ANY,'dough,worm',1,'calm',(10,28),(.04,.5),4,'food,bait','Bites nearly always, if politely asked.','A red eye is how you tell it from a rudd.','A steady silver fish with a red-rimmed eye. Most anglers start here and some never leave.')
D('rudd','Rudd','Scardinius aureus','common',P,'surface','day,dusk','spring,summer,autumn',ANY,'insect,dough',2,'surface',(12,30),(.05,.6),5,'food','Takes insects off the top on warm afternoons.','Upturned mouth, surface feeder.','Brass flanks and scarlet fins. It looks up for its dinner, so you see the swirl before the fish.')
D('gudgeon','Gudgeon','Gobio arenarius','common',P,'bottom',DAY,ANY,ANY,'worm',1,'calm',(8,16),(.01,.08),3,'food,bait','Noses along the bottom in sandy shallows.','One small barbel at each corner of the mouth.','A speckled bottom-grubber with one small whisker. It will bite anything, and looks surprised after.')
D('bleak','Bleak','Alburnus clarus','common',P,'surface','day,dusk','summer,autumn',ANY,'insect,dough',2,'quick',(8,16),(.01,.05),3,'bait','A flash high in the water, gone in the same moment.','Scales were once used to pearl glass beads.','Narrow as a blade and just as bright. Shoals scatter at a shadow.')
D('ruffe','Ruffe','Gymnocephalus aspera','common',P,'bottom',ANY,'autumn,winter,spring',ANY,'worm',2,'cautious',(7,16),(.01,.08),3,'bait','A cold-water nibbler on the mud.','Coated in slime, all spines.','A rough little perch-cousin with a saw for a back and a blue-ringed eye.')
D('bitterling','Bitterling','Rhodeus amarus','common',P,'shallow','day','spring,summer','clear','dough',2,'quick',(4,8),(.002,.012),6,'bait','Shows its colours among the shallows in bright spring sun.','Lays its eggs inside mussels. Truly.','The smallest jewel in the pond: rose flanks and one aqua stroke.')
D('common_carp','Common carp','Cyprinus silvae','common',P,'bottom','dusk,night,dawn','spring,summer,autumn',ANY,'dough,worm',4,'strong',(30,75),(.8,9),10,'food','Bubbles at the lily roots toward evening.','Scale-covered, unlike the mirror.','An olive-gold grazer. Slow to take and in no hurry to leave.')
D('whisker_cat','Whiskered catfish','Silurus barbatus','common',P,'bottom',NIGHT,'spring,summer,autumn',ANY,'worm,baitfish',3,'nocturnal',(25,70),(.3,5),9,'food','Feels its way along the bottom once it is dark.','Tastes with its whole skin.','Flat-headed and mottled, with long whiskers for a night that it cannot see through.')
